styles:
:root{--ink:#0b1225;--muted:#5c667a;--line:#e5e8f0;--blue:#2638a7;--violet:#7a37ff;--orange:#ff6a00;--soft:#f7f8fc;--card:#fff;--max:1180px}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:Arial,Helvetica,sans-serif;color:var(--ink);background:#fff;line-height:1.55}a{color:inherit;text-decoration:none}img{max-width:100%}.wrap{width:min(var(--max),calc(100% - 40px));margin:auto}.top{position:sticky;top:0;z-index:20;background:rgba(255,255,255,.96);border-bottom:1px solid var(--line);backdrop-filter:blur(10px)}.nav{min-height:72px;display:flex;align-items:center;gap:30px}.logo{width:145px}.links{display:flex;gap:22px;align-items:center;margin-left:auto;font-size:14px;font-weight:700}.links a:hover{color:var(--violet)}.navcta{padding:10px 16px;border:1px solid #4d47ff;border-radius:10px;color:#3d35dc}.hero{background:linear-gradient(135deg,#2434a2 0%,#172a87 55%,#46179a 100%);color:#fff;overflow:hidden}.hero .wrap{padding:88px 0 78px;display:grid;grid-template-columns:1.2fr .8fr;gap:52px;align-items:center}.eyebrow{font-size:12px;letter-spacing:.13em;font-weight:800;text-transform:uppercase;color:#b9c8ff}.hero h1{font-size:clamp(42px,5vw,72px);line-height:1.04;margin:14px 0 20px;letter-spacing:-.035em}.hero p{font-size:19px;color:#e6e9ff;max-width:760px}.actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:28px}.btn{display:inline-flex;align-items:center;justify-content:center;padding:13px 19px;border-radius:10px;background:#fff;color:#252e9d;font-weight:800}.btn.alt{background:transparent;border:1px solid rgba(255,255,255,.55);color:#fff}.heroPanel{background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.18);padding:28px;border-radius:24px}.heroPanel strong{display:block;font-size:18px;margin-bottom:14px}.heroPanel ul{margin:0;padding-left:20px;color:#eef0ff}.trust{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--line);border-bottom:1px solid var(--line)}.trust div{background:#fff;padding:18px;text-align:center;font-size:13px;font-weight:800}.section{padding:78px 0}.section.soft{background:var(--soft)}.section h2{font-size:clamp(31px,4vw,48px);line-height:1.08;letter-spacing:-.03em;margin:0 0 14px}.intro{max-width:760px;color:var(--muted);font-size:18px;margin:0 0 34px}.grid4{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.card{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:24px}.card h3{font-size:19px;margin:7px 0 9px}.card p{margin:0;color:var(--muted);font-size:14px}.icon{width:38px;height:38px;border-radius:10px;display:grid;place-items:center;background:#f1edff;color:var(--violet);font-weight:900}.answers{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.answer{background:#fff;border:1px solid var(--line);border-radius:18px;padding:23px}.answer h3{margin:0 0 8px;font-size:17px}.answer p{margin:0;color:var(--muted);font-size:14px}.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;counter-reset:x}.step{padding:23px;border-left:3px solid var(--violet);background:#fff;border-radius:0 16px 16px 0}.step b{font-size:12px;color:var(--violet)}.step h3{margin:8px 0 8px}.step p{color:var(--muted);font-size:14px;margin:0}.local{background:#0c1739;color:#fff;border-radius:24px;padding:38px;display:grid;grid-template-columns:1fr .35fr;gap:30px;align-items:center}.local h2{font-size:36px}.local p{color:#c8d0ea;margin:0}.localTag{border:1px solid rgba(255,255,255,.2);border-radius:18px;padding:20px;text-align:center;font-weight:800}.related{display:flex;flex-wrap:wrap;gap:10px}.chip{padding:10px 14px;border-radius:999px;border:1px solid var(--line);font-size:13px;font-weight:700;background:#fff}.ctaBand{padding:56px 0;background:linear-gradient(90deg,#5c2cff,#283eff);color:#fff}.ctaBand .wrap{display:flex;align-items:center;justify-content:space-between;gap:25px}.ctaBand h2{margin:0;font-size:34px}.footer{background:#080d1b;color:#c9cfdd;padding:50px 0 28px}.footgrid{display:grid;grid-template-columns:1.5fr repeat(3,1fr);gap:30px}.footer h4{color:#fff;margin:0 0 12px}.footer a{display:block;margin:8px 0;font-size:13px}.footer p{font-size:13px}.fine{border-top:1px solid #20283b;margin-top:30px;padding-top:20px;font-size:12px;color:#8d96aa}.seoNote{font-size:13px;color:#687188;margin-top:16px}.mobileMenu{display:none}@media(max-width:900px){.links{display:none}.hero .wrap{grid-template-columns:1fr;padding:64px 0}.grid4,.steps{grid-template-columns:repeat(2,1fr)}.answers{grid-template-columns:1fr}.local{grid-template-columns:1fr}.footgrid{grid-template-columns:1fr 1fr}.trust{grid-template-columns:1fr}.ctaBand .wrap{align-items:flex-start;flex-direction:column}}@media(max-width:560px){.wrap{width:min(var(--max),calc(100% - 28px))}.hero h1{font-size:42px}.hero p{font-size:17px}.grid4,.steps,.footgrid{grid-template-columns:1fr}.section{padding:58px 0}.local{padding:26px}.nav{min-height:64px}.logo{width:125px}}

/* Patch 3 commercial differentiation */
.split2{display:grid;grid-template-columns:1fr 1fr;gap:22px;align-items:stretch}.panelDark{background:#0c1739;color:#fff;border-radius:24px;padding:32px}.panelDark h2,.panelDark h3{color:#fff}.panelDark p{color:#c8d0ea}.featureStrip{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:28px}.featureStrip>div{border:1px solid var(--line);border-radius:14px;padding:16px;background:#fff;font-size:13px;font-weight:800}.matrix{border:1px solid var(--line);border-radius:18px;overflow:hidden;background:#fff}.matrixRow{display:grid;grid-template-columns:.8fr 1.2fr 1.2fr;gap:0;border-top:1px solid var(--line)}.matrixRow:first-child{border-top:0}.matrixRow>*{padding:16px}.matrixRow strong{background:#fafbfe}.tagline{font-size:13px;font-weight:800;color:var(--violet);text-transform:uppercase;letter-spacing:.08em}.stack{display:grid;gap:14px}.stackItem{display:grid;grid-template-columns:56px 1fr;gap:16px;align-items:start;border:1px solid var(--line);border-radius:16px;padding:18px;background:#fff}.stackItem b{display:grid;place-items:center;width:44px;height:44px;border-radius:12px;background:#f1edff;color:var(--violet)}.stackItem h3{margin:0 0 6px}.stackItem p{margin:0;color:var(--muted)}.usecases{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.usecase{border-radius:18px;padding:24px;background:#0c1739;color:#fff}.usecase p{color:#c8d0ea;margin-bottom:0}.callout{border:1px solid #d9d9ff;background:#f5f3ff;border-radius:18px;padding:24px}.callout strong{display:block;margin-bottom:6px}.specGrid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}.spec{border:1px solid var(--line);border-radius:16px;padding:20px;background:#fff}.spec h3{margin:0 0 8px}.spec p{margin:0;color:var(--muted)}.band{padding:30px 0;background:#111a42;color:#fff}.band .wrap{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}.band span{font-size:13px;font-weight:800;color:#d8ddff}.decisionLoop{display:grid;grid-template-columns:repeat(5,1fr);gap:10px}.decisionLoop article{border:1px solid var(--line);border-radius:16px;padding:18px;background:#fff}.decisionLoop b{color:var(--violet);font-size:12px}.decisionLoop h3{font-size:17px;margin:7px 0}.decisionLoop p{font-size:13px;color:var(--muted);margin:0}.screenGrid{display:grid;grid-template-columns:1.1fr .9fr;gap:22px}.screenCards{display:grid;grid-template-columns:1fr 1fr;gap:14px}.screenCard{border:1px solid var(--line);border-radius:16px;padding:18px;background:#fff}.screenCard h3{margin:0 0 7px}.screenCard p{margin:0;color:var(--muted);font-size:14px}.locationGrid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.locationCard{border:1px solid var(--line);border-radius:18px;padding:22px;background:#fff}.locationCard h3{margin:0 0 8px}.locationCard p{margin:0;color:var(--muted)}
@media(max-width:900px){.split2,.screenGrid{grid-template-columns:1fr}.featureStrip,.decisionLoop{grid-template-columns:repeat(2,1fr)}.usecases,.locationGrid{grid-template-columns:1fr}.matrixRow{grid-template-columns:1fr}.matrixRow>*{border-top:1px solid var(--line)}.matrixRow>*:first-child{border-top:0}.specGrid{grid-template-columns:1fr}}
@media(max-width:560px){.featureStrip,.decisionLoop,.screenCards{grid-template-columns:1fr}}


/* Visual V3 - page-specific product storytelling */
.v3Story{position:relative;padding:86px 0;overflow:hidden;background:linear-gradient(180deg,#fff 0%,var(--soft) 100%)}
.v3Story:before{content:"";position:absolute;width:520px;height:520px;border-radius:50%;right:-260px;top:-220px;background:radial-gradient(circle,var(--v3glow,rgba(122,55,255,.13)) 0%,transparent 68%);pointer-events:none}
.v3Shell{position:relative;display:grid;grid-template-columns:1.15fr .85fr;gap:24px;align-items:stretch}
.v3Main,.v3Side{border:1px solid var(--line);border-radius:26px;background:rgba(255,255,255,.9);box-shadow:0 24px 70px rgba(15,23,42,.08)}
.v3Main{padding:34px}.v3Side{padding:28px;background:linear-gradient(145deg,var(--v3dark,#101a45),var(--v3dark2,#1d2665));color:#fff;display:flex;flex-direction:column}
.v3Kicker{font-size:12px;letter-spacing:.12em;font-weight:900;color:var(--v3accent,var(--violet));text-transform:uppercase}.v3Story h2{font-size:clamp(34px,4vw,52px);line-height:1.04;letter-spacing:-.035em;margin:9px 0 14px}.v3Lead{color:var(--muted);font-size:17px;max-width:760px}
.v3Tabs{display:flex;gap:8px;flex-wrap:wrap;margin:28px 0 18px}.v3Tab{appearance:none;border:1px solid var(--line);background:#fff;border-radius:999px;padding:10px 14px;font-weight:800;color:#475069;cursor:pointer;transition:.2s}.v3Tab:hover,.v3Tab[aria-selected="true"]{background:var(--v3accent,var(--violet));color:#fff;border-color:var(--v3accent,var(--violet));transform:translateY(-1px)}
.v3Canvas{min-height:210px;border-radius:22px;padding:28px;background:linear-gradient(135deg,var(--v3soft,#f6f4ff),#fff);border:1px solid color-mix(in srgb,var(--v3accent,var(--violet)) 20%,#e6e8ef);display:grid;grid-template-columns:66px 1fr;gap:20px;align-items:start}
.v3Glyph{width:62px;height:62px;border-radius:18px;display:grid;place-items:center;background:var(--v3accent,var(--violet));color:#fff;font-size:22px;font-weight:900;box-shadow:0 12px 28px color-mix(in srgb,var(--v3accent,var(--violet)) 28%,transparent)}.v3Canvas h3{font-size:25px;margin:1px 0 8px}.v3Canvas p{margin:0;color:var(--muted);font-size:15px}.v3Meter{height:8px;border-radius:999px;background:#e9ecf3;margin-top:20px;overflow:hidden}.v3Meter span{display:block;height:100%;width:25%;border-radius:999px;background:linear-gradient(90deg,var(--v3accent,var(--violet)),var(--v3accent2,#38c7ff));transition:width .28s ease}
.v3Side h3{font-size:23px;margin:0 0 10px}.v3Side p{color:#cdd5ee;margin:0 0 18px}.v3Checklist{display:grid;gap:10px;margin:4px 0 24px}.v3Checklist div{display:flex;gap:11px;align-items:center;padding:12px 13px;border-radius:13px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.1);font-size:14px;font-weight:700}.v3Checklist i{width:24px;height:24px;border-radius:50%;display:grid;place-items:center;background:var(--v3accent2,#38c7ff);color:#071325;font-style:normal;font-size:12px;font-weight:900}.v3Side .btn{margin-top:auto;background:linear-gradient(90deg,var(--v3accent,var(--violet)),var(--v3accent2,#38c7ff));color:#fff;border:0}.v3Mini{margin-top:14px;color:#9facce;font-size:12px}
.v3Orbit{position:relative;height:122px;margin:8px 0 16px}.v3Orbit .core{position:absolute;left:50%;top:50%;width:62px;height:62px;border-radius:50%;transform:translate(-50%,-50%);display:grid;place-items:center;background:#fff;color:var(--v3dark,#101a45);font-weight:900;box-shadow:0 0 0 10px rgba(255,255,255,.07)}.v3Orbit span{position:absolute;padding:7px 10px;border-radius:999px;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.12);font-size:11px;font-weight:800}.v3Orbit span:nth-child(2){left:4%;top:10%}.v3Orbit span:nth-child(3){right:2%;top:14%}.v3Orbit span:nth-child(4){left:8%;bottom:4%}.v3Orbit span:nth-child(5){right:5%;bottom:3%}
@media(max-width:900px){.v3Shell{grid-template-columns:1fr}.v3Story{padding:64px 0}.v3Main{padding:26px}.v3Side{padding:24px}}
@media(max-width:560px){.v3Canvas{grid-template-columns:1fr}.v3Glyph{width:54px;height:54px}.v3Story h2{font-size:36px}.v3Tabs{gap:6px}.v3Tab{padding:9px 11px;font-size:12px}}

.br-home-header,.br-home-footer{font-family:Poppins,Arial,Helvetica,sans-serif}
.br-home-header{background:rgba(255,255,255,.97)!important;border-bottom:0!important}
.br-home-header .container-section{width:min(1280px,calc(100% - 40px));margin:auto}
.br-home-header button.btn{background:transparent;color:#111827;padding:8px;border:0}
.br-home-footer{background:#18182a}
@media(max-width:1023px){.br-home-header .container-section{width:min(100% - 28px,1280px)}#br-mobile-nav{position:absolute;left:0;right:0;top:64px;box-shadow:0 12px 28px rgba(0,0,0,.10)}}

/* Boost RAVA Visual Upgrade V1 */
.page-shell[class*="br-page-"] .hero h1{max-width:900px;text-wrap:balance;text-shadow:0 4px 28px rgba(0,0,0,.20)}
.page-shell[class*="br-page-"] .hero p{text-wrap:pretty}
.page-shell[class*="br-page-"] .heroPanel{transition:transform .28s ease,box-shadow .28s ease}
@media(hover:hover) and (pointer:fine){.page-shell[class*="br-page-"] .heroPanel:hover{transform:translateY(-5px)}}
.page-shell[class*="br-page-"] .section h2{text-wrap:balance}
.page-shell[class*="br-page-"] .card,.page-shell[class*="br-page-"] .answer,.page-shell[class*="br-page-"] .spec,.page-shell[class*="br-page-"] .stackItem,.page-shell[class*="br-page-"] .screenCard,.page-shell[class*="br-page-"] .locationCard{transition:border-color .22s ease,box-shadow .22s ease,transform .22s ease}
.page-shell[class*="br-page-"] .btn{transition:transform .18s ease,box-shadow .18s ease,background .18s ease}
@media(hover:hover) and (pointer:fine){.page-shell[class*="br-page-"] .btn:hover{transform:translateY(-2px)}}
.page-shell[class*="br-page-"] .ctaBand{position:relative;overflow:hidden}.page-shell[class*="br-page-"] .ctaBand:after{content:"";position:absolute;width:240px;height:240px;border-radius:50%;right:-90px;top:-100px;background:rgba(255,255,255,.09)}.page-shell[class*="br-page-"] .ctaBand .wrap{position:relative;z-index:1}
@media(max-width:900px){.page-shell[class*="br-page-"] .hero:before,.page-shell[class*="br-page-"] .hero:after{opacity:.55}.page-shell[class*="br-page-"] .heroPanel{max-width:680px}}
@media(prefers-reduced-motion:reduce){.page-shell[class*="br-page-"] *{scroll-behavior:auto!important;transition:none!important}}

.page-shell.br-page-context{background:#fcfffe}.br-page-context .hero{position:relative;background:radial-gradient(circle at 83% 22%,rgba(243,167,18,.23),transparent 23%),linear-gradient(125deg,#0a2d33,#0d5b60 58%,#11786b)}
.br-page-context .hero:before{content:"";position:absolute;right:3%;bottom:-38%;width:44%;aspect-ratio:1;background:conic-gradient(from 30deg,transparent,rgba(255,255,255,.10),transparent,rgba(255,209,116,.10),transparent);border-radius:50%}.br-page-context .hero .wrap{position:relative;z-index:1}.br-page-context .heroPanel{background:rgba(5,42,47,.64);border:1px solid rgba(255,222,154,.24);box-shadow:0 28px 60px rgba(0,30,31,.33)}
.br-page-context .heroPanel:before{content:"SEMANTIC SIGNAL";display:block;color:#ffe1a6;font-size:10px;letter-spacing:.16em;font-weight:900;margin-bottom:12px}.br-page-context .section.soft{background:linear-gradient(180deg,#f0faf7,#fffaf0)}.br-page-context .card,.br-page-context .answer,.br-page-context .spec{border-color:#dbeeea}.br-page-context .card:nth-child(2n){border-top:3px solid #f3a712}.br-page-context .card:nth-child(2n+1){border-top:3px solid #0f9f8f}.br-page-context .icon,.br-page-context .stackItem b{background:#ddf7f1;color:#0b8d7e}.br-page-context .local{background:linear-gradient(135deg,#0b363a,#106a62)}.br-page-context .ctaBand{background:linear-gradient(90deg,#087f74,#10a392,#e99b0b)}

.br-lab{padding:82px 0;background:linear-gradient(180deg,#f8f9ff 0%,#fff 100%);position:relative;overflow:hidden}
.br-lab:before{content:"";position:absolute;width:420px;height:420px;border-radius:50%;background:radial-gradient(circle,rgba(102,77,255,.12),transparent 68%);top:-180px;right:-120px;pointer-events:none}
.br-lab .labHead{display:flex;align-items:end;justify-content:space-between;gap:26px;margin-bottom:28px}.br-lab .labHead>div:first-child{max-width:780px}
.br-lab .labKicker{font-size:12px;letter-spacing:.12em;text-transform:uppercase;font-weight:900;color:var(--violet)}
.br-lab h2{font-size:clamp(32px,4vw,50px);line-height:1.06;margin:8px 0 12px;letter-spacing:-.035em}.br-lab .labIntro{color:var(--muted);font-size:17px;margin:0}
.br-lab .labGrid{display:grid;grid-template-columns:.92fr 1.08fr;gap:22px;align-items:start}.br-lab .toolCard,.br-lab .resultCard{background:#fff;border:1px solid var(--line);border-radius:24px;padding:26px;box-shadow:0 18px 55px rgba(23,32,79,.08)}
.br-lab .resultCard{background:linear-gradient(145deg,#0e183e,#121f53);color:#fff;border-color:rgba(255,255,255,.1);position:sticky;top:92px}.br-lab .resultCard p{color:#cbd3ef}
.br-lab .fieldGrid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.br-lab .field{display:grid;gap:7px}.br-lab label{font-size:12px;font-weight:850;color:#313a50}.br-lab input,.br-lab select{width:100%;border:1px solid #dfe3ef;border-radius:12px;padding:12px 13px;background:#fbfcff;color:#111827;font:inherit;outline:none}.br-lab input:focus,.br-lab select:focus{border-color:#7568ff;box-shadow:0 0 0 3px rgba(117,104,255,.12)}
.br-lab .metricGrid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-top:18px}.br-lab .metric{border:1px solid rgba(255,255,255,.13);border-radius:16px;padding:16px;background:rgba(255,255,255,.06)}.br-lab .metric span{display:block;color:#bfc8e9;font-size:12px}.br-lab .metric strong{display:block;font-size:24px;margin-top:5px}.br-lab .disclaimer{font-size:11px!important;line-height:1.5;margin:16px 0 0;color:#aeb8d8!important}
.br-lab .presetRow{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0 20px}.br-lab .preset{border:1px solid var(--line);background:#fff;padding:8px 11px;border-radius:999px;font-size:12px;font-weight:800;cursor:pointer}.br-lab .preset:hover,.br-lab .preset[aria-pressed="true"]{background:#171f4d;color:#fff;border-color:#171f4d}
.br-lab .score{display:flex;align-items:center;gap:15px;margin-top:20px}.br-lab .scoreRing{width:84px;height:84px;border-radius:50%;display:grid;place-items:center;background:conic-gradient(#7a37ff var(--pct),rgba(255,255,255,.13) 0);position:relative}.br-lab .scoreRing:after{content:"";position:absolute;inset:8px;background:#111b48;border-radius:50%}.br-lab .scoreRing strong{z-index:1;font-size:21px}
