:root{--brv4-bg:#1b0b22;--brv4-a:#f472b6;--brv4-b:#f59e0b;--brv4-ink:#eef6ff;--brv4-muted:#9db0c9;--brv4-line:rgba(148,163,184,.18);--brv4-card:rgba(255,255,255,.055)}
.page-shell.brv4-page{background:var(--brv4-bg)!important;color:var(--brv4-ink)}
.page-shell.brv4-page::before{content:"";position:fixed;inset:0;pointer-events:none;z-index:-2;background:radial-gradient(circle at 14% 12%,color-mix(in srgb,var(--brv4-a) 19%,transparent),transparent 30%),radial-gradient(circle at 86% 24%,color-mix(in srgb,var(--brv4-b) 15%,transparent),transparent 32%),linear-gradient(180deg,var(--brv4-bg),#060b14 74%)}
.page-shell.brv4-page main,.page-shell.brv4-page .min-h-screen{position:relative}
