.page-shell.brv4-page h2{letter-spacing:-.03em;text-wrap:balance}
.page-shell.brv4-page p{line-height:1.75}
.page-shell.brv4-page a,.page-shell.brv4-page button{transition:transform .22s ease,box-shadow .22s ease,border-color .22s ease,background .22s ease}
@media (hover:hover){.page-shell.brv4-page a:hover,.page-shell.brv4-page button:hover{transform:translateY(-2px)}}
.brv4-kicker{display:inline-flex;align-items:center;gap:.55rem;padding:.5rem .8rem;border:1px solid color-mix(in srgb,var(--brv4-a) 35%,transparent);border-radius:999px;background:color-mix(in srgb,var(--brv4-a) 9%,transparent);color:#fff;font:700 11px/1.2 ui-sans-serif,system-ui;letter-spacing:.12em;text-transform:uppercase;box-shadow:inset 0 0 0 1px rgba(255,255,255,.03)}
.brv4-kicker i{width:7px;height:7px;border-radius:99px;background:var(--brv4-a);box-shadow:0 0 18px var(--brv4-a)}
.brv4-lens{max-width:1180px;margin:42px auto;padding:0 22px}.brv4-lens-inner{position:relative;overflow:hidden;border:1px solid var(--brv4-line);border-radius:28px;background:linear-gradient(145deg,rgba(255,255,255,.075),rgba(255,255,255,.025));box-shadow:0 26px 70px rgba(0,0,0,.28);padding:28px}.brv4-lens-inner:after{content:"";position:absolute;width:300px;height:300px;border-radius:50%;right:-110px;top:-150px;background:var(--brv4-a);opacity:.08;filter:blur(20px);pointer-events:none}.brv4-lens-head{display:flex;justify-content:space-between;gap:20px;align-items:end;flex-wrap:wrap}.brv4-lens h2{font-size:clamp(26px,3vw,42px);margin:8px 0 4px}.brv4-lens p{color:var(--brv4-muted);margin:0;max-width:760px}.brv4-controls{display:flex;gap:10px;flex-wrap:wrap;margin-top:22px}.brv4-controls button{min-height:44px;padding:10px 15px;border-radius:12px;border:1px solid var(--brv4-line);background:rgba(255,255,255,.045);color:#e8f1ff;font-weight:700}.brv4-controls button[aria-pressed="true"]{border-color:color-mix(in srgb,var(--brv4-a) 62%,white 10%);background:linear-gradient(135deg,color-mix(in srgb,var(--brv4-a) 24%,transparent),color-mix(in srgb,var(--brv4-b) 14%,transparent));box-shadow:0 10px 30px color-mix(in srgb,var(--brv4-a) 12%,transparent)}.brv4-result{display:grid;grid-template-columns:1.1fr .9fr;gap:16px;margin-top:18px}.brv4-panel{border:1px solid var(--brv4-line);border-radius:18px;padding:18px;background:rgba(3,9,18,.38)}.brv4-panel strong{display:block;font-size:15px;margin-bottom:8px}.brv4-panel span{color:var(--brv4-muted);font-size:14px;line-height:1.6}.brv4-tags{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.brv4-tags em{font-style:normal;font-size:12px;padding:6px 9px;border-radius:999px;background:color-mix(in srgb,var(--brv4-b) 12%,transparent);border:1px solid color-mix(in srgb,var(--brv4-b) 25%,transparent);color:#eaf5ff}.brv4-meter{height:8px;border-radius:99px;background:rgba(255,255,255,.08);overflow:hidden;margin-top:14px}.brv4-meter b{di