/* Performance-safe motion: CSS only, transform/opacity, no layout animation. */
:where(.br-page-advertiser,.br-page-publisher,.br-page-ai,.br-page-context,.br-page-rich,.br-page-html5,.br-page-ctv,.br-page-dooh,.brv4-page) a,
:where(.br-page-advertiser,.br-page-publisher,.br-page-ai,.br-page-context,.br-page-rich,.br-page-html5,.br-page-ctv,.br-page-dooh,.brv4-page) button{
  transition:color .2s ease,background-color .2s ease,border-color .2s ease,box-shadow .25s ease,transform .25s ease,opacity .2s ease;
}
:where(.br-page-advertiser,.br-page-publisher,.br-page-ai,.br-page-context,.br-page-rich,.br-page-html5,.br-page-ctv,.br-page-dooh,.brv4-page) :is(a,button,input,select,textarea):focus-visible{
  outline:3px solid color-mix(in srgb,var(--accent,#3b82f6) 52%,#fff);outline-offset:3px;
}
:where(.br-page-advertiser,.br-page-publisher,.br-page-ai,.br-page-context,.br-page-rich,.br-page-html5,.br-page-ctv,.br-page-dooh,.brv4-page) :is(.card,.br-format-card,.v3Main,.v3Side,.v3Canvas,.featureStrip,.br-preview,.br-lab){
  will-change:auto;backface-visibility:hidden;transform:translateZ(0);
  transition:transform .28s cubic-bezier(.2,.7,.2,1),box-shadow .28s ease,border-color .25s ease,background-color .25s ease;
}
@media (hover:hover) and (pointer:fine){
  :where(.br-page-advertiser,.br-page-publisher,.br-page-ai,.br-page-context,.br-page-rich,.br-page-html5,.br-page-ctv,.br-page-dooh,.brv4-page) :is(.card,.br-format-card,.v3Canvas,.br-preview,.br-lab):hover{
    transform:translate3d(0,-6px,0);box-shadow:0 22px 50px rgba(15,23,42,.12);
  }
  :where(.br-page-advertiser,.br-page-publisher,.br-page-ai,.br-page-context,.br-page-rich,.br-page-html5,.br-page-ctv,.br-page-dooh,.brv4-page) :is(.v3Main,.v3Side):hover{
    transform:translate3d(0,-4px,0);
  }
  :where(.br-page-advertiser,.br-page-publisher,.br-page-ai,.br-page-context,.br-page-rich,.br-page-html5,.br-page-ctv,.br-page-dooh,.brv4-page) a.btn:hover,
  :where(.br-page-advertiser,.br-page-publisher,.br-page-ai,.br-page-context,.br-page-rich,.br-page-html5,.br-page-ctv,.br-page-dooh,.brv4-page) button.btn:hover{
    transform:translate3d(0,-3px,0);box-shadow:0 14px 30px rgba(15,23,42,.16);
  }
  :where(.br-page-advertiser,.br-page-publisher,.br-page-ai,.br-page-context,.br-page-rich,.br-page-html5,.br-page-ctv,.br-page-dooh,.brv4-page) .v3Checklist div:hover{
    transform:translateX(4px);background:rgba(255,255,255,.12);
  }
}
/* Motion should never hide SEO-visible content. */
:where(.br-page-advertiser,.br-page-publisher,.br-page-ai,.br-page-context,.br-page-rich,.br-page-html5,.br-page-ctv,.br-page-dooh,.brv4-page) :is(h1,h2,h3,p,li){opacity:1!important}
/* Touch/mobile: no hover lift; preserve stable layout. */
@media (max-width:768px),(hover:none){
  :where(.br-page-advertiser,.br-page-publisher,.br-page-ai,.br-page-context,.br-page-rich,.br-page-html5,.br-page-ctv,.br-page-dooh,.brv4-page) :is(.card,.br-format-card,.v3Main,.v3Side,.v3Canvas,.br-preview,.br-lab){transform:none!important}
}
@media (prefers-reduced-motion:reduce){
  :where(.br-page-advertiser,.br-page-publisher,.br-page-ai,.br-page-context,.br-page-rich,.br-page-html5,.br-page-ctv,.br-page-dooh,.brv4-page) *,
  :where(.br-page-advertiser,.br-page-publisher,.br-page-ai,.br-page-context,.br-page-rich,.br-page-html5,.br-page-ctv,.br-page-dooh,.brv4-page) *::before,
  :where(.br-page-advertiser,.br-page-publisher,.br-page-ai,.br-page-context,.br-page-rich,.br-page-html5,.br-page-ctv,.br-page-dooh,.brv4-page) *::after{
    scroll-behavior:auto!important;animation-duration:.001ms!important;animation-iteration-count:1!important;transition-duration:.001ms!important;
  }
}

