.bd-metadata-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.bd-metadata-grid article{border:1px solid var(--line);border-radius:16px;padding:19px;background:#fff}.bd-metadata-grid strong{display:block;margin-bottom:7px;color:#2638a7}.bd-metadata-grid span{color:var(--muted);font-size:14px}.bd-measurement-note{margin-top:18px}
.bd-settings .matrixRow{grid-template-columns:.55fr 1.15fr 1.3fr}.bd-settings .matrixRow:first-child{background:#111a42;color:#fff}.bd-settings .matrixRow:first-child strong{background:transparent;color:#fff}
.bd-verify-flow{display:grid;grid-template-columns:1fr auto 1fr auto 1fr auto 1fr;gap:10px;align-items:stretch}.bd-verify-flow article{border:1px solid var(--line);border-radius:18px;padding:20px;background:#fff}.bd-verify-flow b{font-size:10px;letter-spacing:.1em;color:#5d45ff}.bd-verify-flow h3{margin:8px 0}.bd-verify-flow p{margin:0;color:var(--muted);font-size:14px}.bd-verify-flow i{display:grid;place-items:center;font-style:normal;color:#5d45ff;font-weight:900}
.bd-dual-flow{display:grid;grid-template-columns:1fr 1fr;gap:18px}.bd-role{border-radius:22px;padding:26px;background:linear-gradient(145deg,#111a42,#172d69);color:#fff}.bd-role.screen{background:linear-gradient(145deg,#20154c,#123f5d)}.bd-role>span{font-size:11px;font-weight:900;letter-spacing:.1em;color:#8deeff}.bd-role h3{color:#fff;font-size:24px;margin:8px 0 12px}.bd-role ol{margin:0;padding-left:20px;color:#d6e3f6}.bd-role li{margin:7px 0}
@media(max-width:1000px){.bd-flow,.bd-architecture,.bd-verify-flow{grid-template-columns:1fr}.bd-flow i,.bd-arch-arrow,.bd-verify-flow i{transform:rotate(90deg);height:18px}.bd-venue-grid,.bd-step-grid{grid-template-columns:repeat(2,1fr)}.bd-metadata-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:700px){.bd-distinct-grid,.bd-dual-flow,.bd-venue-grid,.bd-step-grid,.bd-metadata-grid{grid-template-columns:1fr}.bd-settings .matrixRow{grid-template-columns:1fr}.bd-settings .matrixRow>*{border-top:1px solid var(--line)}.bd-settings .matrixRow>*:first-child{border-top:0}.bd-activation-map{padding:18px!important}}
